# -*- coding: utf-8 -*-
import pathlib,json,html
P=pathlib.Path(__file__).resolve().parents[1];xs=json.loads((P/'catalog/papers.json').read_text());st=json.loads((P/'catalog/stats.json').read_text())
data=json.dumps(xs,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>金融文本预测：代表性论文地图</title><style>body{font:16px/1.8 system-ui,"PingFang SC",sans-serif;margin:0;background:#edf3f7;color:#173247}main{max-width:1100px;margin:28px auto;padding:36px;background:white;border-radius:10px}h1{font-size:28px}h3{font-size:18px;margin:0 0 8px}a{color:#126185;text-decoration:none}a:hover{text-decoration:underline}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0}input,select,button{font:inherit;border:1px solid #b9cbd8;border-radius:6px;padding:9px 12px;background:white}input{flex:1;min-width:280px}.card{padding:22px 0;border-bottom:1px solid #d9e5ed}.meta{color:#617989;font-size:13px}.note{background:#edf5fa;padding:12px;margin-top:10px}.banner{padding:15px;background:#f4f7ec}.tag{display:inline-block;padding:2px 8px;border-radius:12px;background:#e4eef5;margin:3px;font-size:12px}@media(max-width:600px){main{margin:0;padding:20px}input{min-width:100%}}</style><main><h1>金融文本与时序预测：代表性论文地图</h1><p>共 TOTAL 条文献 · REP 篇代表 · TECH 条技术路线 · VIEW 组观点与争议 · PDF 份可公开全文</p><p><a href="docs/代表性论文地图.md">代表性地图</a> · <a href="docs/技术路线覆盖表.md">技术覆盖</a> · <a href="docs/观点与争议覆盖表.md">观点覆盖</a> · <a href="README.md">项目说明</a></p><p class="banner">数量按覆盖需要确定，不设固定先读篇数。说明与导读使用中文；英文原题名保留用于正式引用。近期预印本、局部诊断和经典方法分别标记，不把它们视为同等成熟的共识。</p><div class="controls"><input id="q" aria-label="搜索" placeholder="中文导读、原始题名、作者、DOI或观点"><select id="scope" aria-label="范围"><option value="all">全部文献</option><option value="rep">代表论文</option><option value="pdf">可公开全文</option><option value="recent">2025—2026题录</option></select><select id="cat" aria-label="分类"><option value="">全部分类</option>CATS</select><button id="reset">重置</button></div><div id="count"></div><section id="list"></section></main><script>
const D=DATA;const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function draw(){const q=$('#q').value.trim().toLowerCase(),s=$('#scope').value,c=$('#cat').value;const a=D.filter(x=>(!q||[x.id,x.title_zh,x.title,x.authors,x.doi,...x.tags,x.curated_note?.finding,x.curated_note?.caveat].join(' ').toLowerCase().includes(q))&&(!c||x.category===c)&&(s==='all'||s==='rep'&&x.representative||s==='pdf'&&x.pdf_path||s==='recent'&&x.date.slice(0,4)>='2025'));$('#count').textContent=`显示 ${a.length} / ${D.length} 条`;$('#list').innerHTML=a.map(x=>`<article class="card"><h3>${x.representative?'★ ':''}${x.id} · <a href="papers/${x.id}.md">${esc(x.title_zh||'金融文本预测文献')}</a></h3><div class="meta">原文题名：${esc(x.title)}</div><div>${esc(x.authors)}</div><div class="meta">${esc(x.date)} · ${esc(x.venue)}</div><p>${x.pdf_path?`<a href="${esc(x.pdf_path)}">阅读公开全文</a> · `:''}<a href="${esc(x.url)}" target="_blank" rel="noopener">原文入口</a></p><div>${x.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="meta">${esc(x.read_level)}</div>${x.curated_note?`<div class="note">${esc(x.curated_note.finding)}<br>边界：${esc(x.curated_note.caveat)}</div>`:''}</article>`).join('')}
for(const e of document.querySelectorAll('input,select'))e.addEventListener('input',draw);$('#reset').onclick=()=>{$('#q').value='';$('#scope').value='all';$('#cat').value='';draw()};draw();
</script></html>'''
page=page.replace('TOTAL',str(st['total'])).replace('REP',str(st['representatives'])).replace('TECH',str(st['technical_axes'])).replace('VIEW',str(st['viewpoint_axes'])).replace('PDF',str(st['public_pdfs'])).replace('DATA',data)
catnames={x['category'] for x in xs};names={'01-incremental-value':'文本增量：收益与价格','02-volatility-risk':'波动率与风险','03-fusion-alignment':'融合与结构','04-representation':'文本表示','05-evaluation-leakage':'评估与反证','06-small-llms':'小模型与时序适配','07-benchmarks-surveys':'数据集与基准','08-macro-cross-assets':'宏观与跨资产','09-adjacent':'决策与邻接研究'}
page=page.replace('CATS',''.join(f'<option value="{c}">{names[c]}</option>' for c in sorted(catnames)));(P/'index.html').write_text(page)
print('中文交互入口已生成')
